def classify(title: str, cwe_ids: list[str] | None = None) -> tuple[str, str, str, str]:
    """-> (issue_key, canonical CWE, canonical title, remediation). Falls back to a tool-neutral slug."""
    t = (title or "").lower()
    if re.search(r"\bdeprecated\b|\breplaced with\b", t) and "header" in t:
        # informational note about a header that IS present; must not be merged with "header missing" findings
        return f"info:{re.sub(r'[^a-z0-9]+', '-', t)[:50]}", "", title, ""
    for key, rx, cwe, ctitle, fix in ISSUE_CLASSES:
        if re.search(rx, t):
            return key, cwe, ctitle, fix
    cw = (cwe_ids or [""])[0]
    return (f"other:{re.sub(r'[^a-z0-9]+', '-', t)[:60]}" if not cw else f"cwe:{cw}:{re.sub(r'[^a-z0-9]+', '-', t)[:40]}"), cw, title, ""


def cwe_info(cwe: str) -> tuple[str, str]:
    return CWE.get(cwe, ("", ""))


def kev(cve: str) -> bool:
    return cve.upper() in KEV_PARTIAL


def known_version_cves(product: str, version: str) -> list[dict]:
    out = []
    for r in KNOWN_VULNERABLE_VERSIONS:
        if re.search(r["product"], (product or "").lower()) and re.search(r["version"], version or ""):
            out.append(r)
    return out
